// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        address originalAdmin = address(this);
        bool isAdmin = (caller == originalAdmin);

        address ownerBefore = c.owner();

        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool) { ok = true; } catch { ok = false; }

        address ownerAfter = c.owner();

        bool testPassed;
        if (isAdmin) {
            testPassed = (ok && ownerAfter == newOwner);
        } else {
            testPassed = (!ok && ownerAfter == ownerBefore);
        }

        assertTrue(testPassed);
    }
}
